import sys

class Node:
    def __init__(self, name, duration):
        self.name = name
        self.duration = duration
        self.prev = None
        self.next = None

def main():
    head = None
    tail = None
    current = None
    track_map = {}

    q = int(sys.stdin.readline().strip())

    for _ in range(q):
        line = sys.stdin.readline().strip()
        if not line:
            continue

        parts = line.split()
        op = parts[0]

        if op == "PUSH":
            name = parts[1]
            duration = int(parts[2])
            new_node = Node(name, duration)

            if head is None:
                head = new_node
                tail = new_node
                current = new_node
            else:
                new_node.prev = tail
                tail.next = new_node
                tail = new_node

            track_map[name] = new_node

        elif op == "REMOVE":
            name = parts[1]
            if name not in track_map:
                print("Track not found")
            else:
                node = track_map[name]

                if node.prev:
                    node.prev.next = node.next
                else:
                    head = node.next

                if node.next:
                    node.next.prev = node.prev
                else:
                    tail = node.prev

                if current == node:
                    current = node.next if node.next else node.prev

                del track_map[name]

        elif op == "FORWARD":
            if current and current.next:
                current = current.next
            else:
                print("No forward track")

        elif op == "BACK":
            if current and current.prev:
                current = current.prev
            else:
                print("No backward track")

        elif op == "SHOW":
            if current is None:
                continue

            names = []
            temp = current
            while temp:
                names.append(temp.name)
                temp = temp.next

            print(" ".join(names))

if __name__ == "__main__":
    main()
